<?php
declare(strict_types=1);require_once __DIR__.'/estimate_common.php';$user=billing_require_admin();production_require_method('GET');accounts_endpoint(function():array{$db=production_db();$id=(int)($_GET['id']??0);if($id>0){$s=$db->prepare('SELECT e.*,r.reference_no revision_reference_no FROM qbook_estimates e LEFT JOIN qbook_estimates r ON r.id=e.revision_of_estimate_id WHERE e.id=?');$s->execute([$id]);$e=$s->fetch();if(!$e)accounts_fail('ESTIMATE_NOT_FOUND',404);$e=estimate_display($e);if($e['revision_reference_no'])$e['revision_of_reference']=billing_ref('ESTIMATE',$e['revision_reference_no']);$l=$db->prepare("SELECT l.*,COALESCE((SELECT SUM(c.converted_quantity) FROM qbook_estimate_invoice_conversions c WHERE c.estimate_line_id=l.id AND c.status IN('DRAFT','COMMITTED')),0) converted_quantity,COALESCE((SELECT SUM(c.converted_entered_amount) FROM qbook_estimate_invoice_conversions c WHERE c.estimate_line_id=l.id AND c.status IN('DRAFT','COMMITTED')),0) converted_amount FROM qbook_estimate_lines l WHERE l.estimate_id=? ORDER BY l.line_no");$l->execute([$id]);$lines=$l->fetchAll();foreach($lines as&$line){$line['remaining_quantity']=$line['quantity']===null?null:number_format(max(0,(float)$line['quantity']-(float)$line['converted_quantity']),4,'.','');$line['remaining_amount']=number_format(max(0,(float)$line['entered_amount']-(float)$line['converted_amount']),2,'.','');}unset($line);$g=$db->prepare("SELECT i.id,i.reference_no,i.status,i.total_amount FROM qbook_invoices i WHERE i.origin_estimate_id=? ORDER BY i.id");$g->execute([$id]);$generated=$g->fetchAll();foreach($generated as&$invoice)$invoice['reference']=billing_ref('INVOICE',$invoice['reference_no']);unset($invoice);return['estimate'=>$e,'lines'=>$lines,'generated_invoices'=>$generated];}$rows=$db->query('SELECT * FROM qbook_estimates ORDER BY COALESCE(estimate_date,DATE(created_at)) DESC,id DESC')->fetchAll();foreach($rows as&$row)$row=estimate_display($row);unset($row);return['estimates'=>$rows];});
